WITH valid AS (SELECT *, COALESCE(page, 'unassigned') AS page_filled FROM web_events WHERE event_time > TIMESTAMP '2023-04-21 13:00:00' AND page IS NOT NULL) SELECT *, ROW_NUMBER() OVER (PARTITION BY page ORDER BY duration_sec, id) AS row_seq, SUM(duration_sec) OVER (PARTITION BY event_type, session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, PERCENT_RANK() OVER (ORDER BY duration_sec NULLS FIRST) AS duration_sec_percent_rank FROM valid
